(()=>{'use strict';
const $=s=>document.querySelector(s), D=window.H3_DATA, R=window.H3Rules, A=window.H3Audio;
const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const modal=$('#modal'),body=$('#dialogBody');let selected=0,m=D.missions[0],s=null,t=null,running=false,readyWorld=false,target=null,noticeTimer,engineAudio=null,loading=false,loadToken=0,lastCitizen=null,chatCitizen=null,currentChat=null;
let completed={},settings={quality:'auto',effects:true,effectsVolume:.55,sound:true,music:true,musicVolume:.28,speechVolume:.9,audioVersion:0,tutorial:false};try{completed=JSON.parse(localStorage.getItem('h3-city-completed')||'{}');settings={...settings,...JSON.parse(localStorage.getItem('h3-city-settings')||'{}')}}catch{}
const BONUS_KEY='h3-city-bonus-pub';let bonusActive=false,bonusReached=false,bonusRecord=null;
try{const record=JSON.parse(localStorage.getItem(BONUS_KEY)||'null');if(record?.id==='gcb-pub'&&typeof record.finished==='string')bonusRecord=record}catch{}
if(settings.audioVersion!==3){settings={...settings,sound:true,music:true,musicVolume:.28,speechVolume:.9,audioVersion:3};}A?.setSpeech(settings.sound);A?.setMusic(settings.music);A?.setMusicVolume(settings.musicVolume);A?.setSpeechVolume(settings.speechVolume);A?.setEffects?.(settings.effects);A?.setEffectsVolume?.(settings.effectsVolume);
let voice=null,spokenKey=null;function store(){try{localStorage.setItem('h3-city-completed',JSON.stringify(completed));localStorage.setItem('h3-city-settings',JSON.stringify(settings))}catch{}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#toast').classList.remove('show'),5200)}
function stopVoice(){A?.stopSpeech();if(voice){voice.pause();voice=null}if('speechSynthesis'in window)window.speechSynthesis.cancel();spokenKey=null}
function speak(key,text){stopVoice();if(!settings.sound)return;spokenKey=key;if(A){A.speak(m.id+'_'+key,text,{sex:m.patient.sex});return}const asset=D.voices?.[m.id]?.[key];if(asset){voice=new Audio(asset);voice.volume=.85;voice.playbackRate=1;voice.preservesPitch=true;voice.play().catch(()=>toast('Ton konnte nicht gestartet werden. Der Gesprächstext bleibt sichtbar.'));return}if('speechSynthesis'in window){const u=new SpeechSynthesisUtterance(text);u.lang='de-CH';u.rate=1.05;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='de-CH')||voices.find(v=>v.lang.startsWith('de'))||null;speechSynthesis.speak(u)}}
function setSound(){settings.sound=!settings.sound;A?.setSpeech(settings.sound);if(!settings.sound)stopVoice();store()}
function audioPanel(){A?.unlock();panel('BILD UND TON','Deine Einstellungen',`<div class="audioSetting"><label for="qualitySelect">Bildqualität</label><select id="qualitySelect" aria-label="Bildqualität"><option value="auto" ${settings.quality==='auto'?'selected':''}>Automatisch</option><option value="high" ${settings.quality==='high'?'selected':''}>Hohe Bildschärfe</option><option value="smooth" ${settings.quality==='smooth'?'selected':''}>Flüssigere Darstellung</option></select><p class="small">Automatisch passt die Bildschärfe an dein Gerät an. Der Spielablauf bleibt gleich.</p></div><div class="audioSetting"><label><input id="musicOn" type="checkbox" ${settings.music?'checked':''}> Hintergrundmusik</label><label for="musicVolume" class="small">Musiklautstärke</label><input id="musicVolume" aria-label="Musiklautstärke" type="range" min="0" max="100" value="${Math.round(settings.musicVolume*100)}"></div><div class="audioSetting"><label><input id="effectsOn" type="checkbox" ${settings.effects?'checked':''}> Motor- und Fahrgeräusche</label><label for="effectsVolume" class="small">Fahrgeräusche</label><input id="effectsVolume" aria-label="Fahrgeräusche" type="range" min="0" max="100" value="${Math.round(settings.effectsVolume*100)}"></div><div class="audioSetting"><label><input id="speechOn" type="checkbox" ${settings.sound?'checked':''}> Gesprochene Missionen und Gespräche</label><label for="speechVolume" class="small">Sprachlautstärke</label><input id="speechVolume" aria-label="Sprachlautstärke" type="range" min="0" max="100" value="${Math.round(settings.speechVolume*100)}"></div><p class="small" style="margin-top:16px">Zu Fuss läuft Musik. Im Fahrzeug hörst du Motor, Reifen und Fahrtwind statt der Musik. Während Gesprächen wird der Hintergrund leiser; alle Texte bleiben lesbar.</p><div class="actions">${button('Zurück zum Spiel','close')}</div>`);$('#qualitySelect').onchange=e=>{settings.quality=e.target.value;Drive.setQuality?.(settings.quality);store()};$('#musicOn').onchange=e=>{settings.music=e.target.checked;A?.setMusic(settings.music);if(running)A?.resumeMusic();store()};$('#effectsOn').onchange=e=>{settings.effects=e.target.checked;A?.setEffects?.(settings.effects);store()};$('#effectsVolume').oninput=e=>{settings.effectsVolume=+e.target.value/100;A?.setEffectsVolume?.(settings.effectsVolume);store()};$('#speechOn').onchange=e=>{settings.sound=e.target.checked;A?.setSpeech(settings.sound);store()};$('#musicVolume').oninput=e=>{settings.musicVolume=+e.target.value/100;A?.setMusicVolume(settings.musicVolume);store()};$('#speechVolume').oninput=e=>{settings.speechVolume=+e.target.value/100;A?.setSpeechVolume(settings.speechVolume);store()}}
function missionBrief(){const text=A?.briefings?.[m.id]||`Begleite ${m.patient.name} von ${m.pickup.label} nach ${m.dropoff.label}. Kläre den Bedarf, bereite die nötigen Dinge vor und suche das passende Fahrzeug für die Fahrt.`;panel('DEIN TRANSPORTAUFTRAG',m.title,`<div class="quote">${esc(text)}</div><div class="dataRow"><b>Abholung</b>${esc(m.pickup.label)} · ${esc(m.pickupTime)}</div><div class="dataRow"><b>Ziel und Termin</b>${esc(m.dropoff.label)} · ${esc(m.appointmentTime)}</div><p style="margin-top:18px">Zu Fuss siehst du deine Figur. Beim Einsteigen siehst du den Wagen von hinten. Mit den Pfeiltasten bewegst du dich; nach zwei Sekunden Vorwärtsgehen rennst du automatisch; Enter öffnet Gespräche und Fahrzeugangebote. M zeigt die Karte.</p><div class="actions">${button('Auftrag annehmen','close')}${button('Erklärung nochmals hören','rebrief','','secondary')}</div>`);if(settings.sound)A?.speak('brief_'+m.id,text,{sex:'female'})}
function panel(label,title,html,conversation=false){A?.setScenePaused?.(true);stopVoice();if(running)Drive.pause();modal.classList.toggle('conversation',conversation);$('#dialogLabel').textContent=label;body.innerHTML=`<h2 class="dialogTitle">${esc(title)}</h2>`+html;if(!modal.open)modal.showModal();modal.scrollTop=0;bind();focusPanelAction()}
function focusPanelAction(){
 const field=body.querySelector('input:not([disabled]):not([type="hidden"]),select:not([disabled]),textarea:not([disabled])');
 const action=body.querySelector('button.question:not(.asked):not([disabled])')||body.querySelector('button.primary:not([disabled])')||body.querySelector('button:not([disabled])');
 const focus=field||action||modal;if(focus===modal)modal.setAttribute('tabindex','-1');focus.focus();
}
function inTextControl(node){return !!node?.closest?.('input,textarea,select,[contenteditable=""],[contenteditable="true"],[role="textbox"]')}
function dialogKeyboard(e){
 if(e.code!=='ArrowUp'&&e.code!=='ArrowDown')return;
 const button=(e.target||document.activeElement)?.closest?.('button');if(!button)return;
 const actions=[...body.querySelectorAll('button:not([disabled]):not([hidden])')].filter(b=>!b.getClientRects||b.getClientRects().length);
 if(!actions.length)return;e.preventDefault();const current=actions.indexOf(button),offset=e.code==='ArrowDown'?1:-1;
 actions[current<0?(offset>0?0:actions.length-1):(current+offset+actions.length)%actions.length].focus();
}
function closePanel(){if(loading)return;A?.setScenePaused?.(false);stopVoice();modal.close();if(running&&!s?.finished){Drive.resume();A?.resumeMusic()}}
function button(label,action,id='',cls='primary'){return `<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`}
function bind(){body.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>act(el.dataset.action,el.dataset.id))}
function act(a,id){if(a==='beginbonus')return beginBonus();if(a==='bonusjournal'){if(bonusActive)bonusJournal();return;}if(a==='bonuscontinue'){if(bonusActive)closePanel();return;}if(bonusActive&&['ask','pack','prepare','approve','board','handover','finish','export','sources','replay','rebrief','navpickup','navdrop'].includes(a)){bonusJournal();return;}if(a==='navpub'){if(!running||!bonusUnlocked())return;navigate({...pubPlace});closePanel();toast('GCB Pub ist vor dem Eingang markiert.');return;}if(a==='pubfood'){orderPubMeal(id);return;}if(a==='close')closePanel();if(a==='chatmore')citizenPanel(chatCitizen);if(a==='chatreplay'&&currentChat){if(!settings.sound)setSound();A?.speak(currentChat.key,currentChat.text,{sex:currentChat.sex})};if(a==='rebrief')missionBrief();if(a==='begin')begin(+id);if(a==='ask')ask(id);if(a==='pack')packPanel();if(a==='prepare')prepare();if(a==='vehicle')vehiclePanel(id);if(a==='approve')approveVehicle(id);if(a==='enter')enter(id);if(a==='exit')exit();if(a==='board')board();if(a==='handover')handover();if(a==='finish')finish();if(a==='journal')journal();if(a==='map')mapPanel();if(a==='navvehicle')navVehicle(id);if(a==='navpickup'){navigate(m.pickup);closePanel();toast('Abholort ist markiert.')}if(a==='next'){closePanel();begin(Math.min(D.missions.length-1,selected+1))}if(a==='home')home();if(a==='export')exportReport();if(a==='sources')sources();if(a==='replay'){if(!settings.sound)setSound();const q=m.dialogue.find(q=>q.id===id);speak(id,q?.answer||m.patient.quote)}}

const pubPlace={x:-90.4,z:-15,label:'GCB Pub'};
const pubMeals=[
 {id:'burger',name:'Pub-Burger',description:'Im Brioche-Bun mit knackigem Salat.'},
 {id:'flammkuchen',name:'Flammkuchen',description:'Knusprig und frisch aus dem Ofen.'},
 {id:'fries',name:'Pommes',description:'Goldbraun gebacken, mit einem Dip.'},
 {id:'salad',name:'Salatteller',description:'Bunter Blattsalat mit frischem Gemüse.'}
];
function pubPanel(){
 if(!t?.nearPubCounter){toast('Komm zum Tresen im GCB Pub.');return;}
 const pending=t.pubOrderState==='preparing';
 panel('GCB PUB','Was darf’s sein?',`<div class="quote">Kellner: «${pending?'Deine Bestellung wird gerade frisch zubereitet.':'Schön, dass du da bist. Such dir etwas aus!'}»</div>${pending?'':`<div class="vehicleList">${pubMeals.map(q=>`<button type="button" data-action="pubfood" data-id="${q.id}"><strong>${q.name}</strong><small>${q.description}</small></button>`).join('')}</div>`}<p class="small">Dein Gericht wird direkt auf dem Tresen serviert. Mit den Pfeiltasten auswählen und mit Enter bestellen.</p><div class="actions">${button('Zurück ins Pub','close','','secondary')}</div>`);
}
function orderPubMeal(id){
 const meal=pubMeals.find(q=>q.id===id);if(!meal)return;
 if(!Drive.orderPubFood?.(id)){toast('Komm zum Tresen oder warte kurz auf deine laufende Bestellung.');return;}
 closePanel();toast('Kellner: «Sehr gern! '+meal.name+' kommt gleich.»');
}

function bonusUnlocked(){return D.missions.every(c=>!!completed?.[c.id]);}
function bonusHelp(){return bonusUnlocked()?'<p class="small">Zusatzmission 6 ist freigeschaltet: Öffne die Karte mit M und wähle «GCB Pub finden». Am Tresen kannst du beim Kellner etwas bestellen.</p>':'';}
function bonusJournal(){
 if(!bonusActive)return;
 panel('ZUSATZMISSION 6',bonusReached?'GCB Pub gefunden':'Finde das GCB Pub',`<div class="info"><strong>${bonusReached?'Geschafft!':'Dein Zusatzauftrag'}</strong><p>${bonusReached?'Du hast das Pub am Quai betreten. Jetzt kannst du dich frei umschauen und beim Kellner etwas bestellen.':'Finde das GCB Pub am Quai und tritt ein. Die Karte hilft dir auf dem Weg. Du startest am gewohnten Ort in Lindenhafen.'}</p></div><p class="small">Eine zusätzliche Entdeckung nach deinen fünf Transportmissionen.</p><div class="actions">${button(bonusReached?'Weiter erkunden':'Losgehen','bonuscontinue')}${button('Karte öffnen','map','','secondary')}${button('Transportauswahl','home','','secondary')}</div>`);
}
function bonusContextLabel(){
 if(t.exitPending)return 'Wird angehalten …';if(t.enterPending)return 'Wagen hält an …';
 if(t.nearPubCounter)return t.pubOrderState==='preparing'?'Dein Gericht wird zubereitet …':'Beim Kellner bestellen';
 if(t.mode==='car')return t.vehicleKind==='scooter'?'Absteigen':'Aussteigen';
 if(t.nearVehicle)return t.nearVehicle.name+' ansehen';if(t.nearCitizen)return 'Passantin oder Passanten ansprechen';
 return bonusReached?'Weiter erkunden':'Zusatzauftrag ansehen';
}
async function beginBonus(){
 if(loading||!bonusUnlocked())return false;
 loading=true;const token=++loadToken;bonusActive=true;bonusReached=false;s=null;t=null;lastCitizen=chatCitizen=currentChat=null;target={...pubPlace};
 await A?.unlock();if(token!==loadToken)return false;A?.pauseMusic();stopVoice();Drive.pause?.();
 panel('EINEN MOMENT','Deine Stadt wird vorbereitet.',`<p>Dein Zusatzauftrag startet gleich.</p><p role="status" id="loadingStatus">Fahrzeuge werden vorbereitet …</p>`);$('#closeDialog').hidden=true;await new Promise(requestAnimationFrame);
 try{
  await window.H3Vehicles?.preload?.();if(token!==loadToken)return false;
  running=true;$('#home').hidden=true;$('#game').hidden=false;document.body.classList.add('playing');['journalBtn','mapBtn','pauseBtn'].forEach(id=>$('#'+id).hidden=false);
  Drive.init($('#city'),telemetry,onWorldAction);readyWorld=true;Drive.setQuality?.(settings.quality||'auto');
  if(!Drive.clearMission?.())throw new Error('Die freie Stadt konnte nicht vorbereitet werden.');
  target={...pubPlace};Drive.setTarget(target);$('#loadingStatus').textContent='Gleich geht es los …';await Drive.ready?.();if(token!==loadToken)return false;
  Drive.resize();loading=false;$('#closeDialog').hidden=false;modal.close();Drive.resume();A?.resumeMusic();update();bonusJournal();return true;
 }catch(e){
  if(token!==loadToken)return false;bonusActive=false;running=false;loading=false;$('#closeDialog').hidden=false;Drive.pause?.();
  panel('GRAFIKSTART','Die Stadt konnte nicht starten',`<p>${esc(e.message)}</p><div class="actions">${button('Erneut versuchen','beginbonus')}${button('Zur Transportauswahl','home','','secondary')}</div>`);console.error(e);return false;
 }
}
function completeBonusIfInside(info){
 if(!bonusActive||bonusReached||!bonusUnlocked()||!running||loading||info.mode!=='walk'||info.pubLocation!=='inside')return false;
 bonusReached=true;
 if(!bonusRecord){bonusRecord={id:'gcb-pub',finished:new Date().toISOString()};try{localStorage.setItem(BONUS_KEY,JSON.stringify(bonusRecord))}catch{}}
 target=null;Drive.setTarget(null);update();updateGuidance(info);renderCards();
 panel('ZUSATZMISSION 6','GCB Pub gefunden',`<div class="info"><strong>Geschafft!</strong><p>Du hast das GCB Pub am Quai gefunden und bist hineingegangen.</p></div><p>Schau dich um und bestelle beim Kellner etwas zu essen. Deine fünf Transportmissionen bleiben abgeschlossen.</p><div class="actions">${button('Weiter erkunden','bonuscontinue')}${button('Transportauswahl','home','','secondary')}</div>`);return true;
}

function renderCards(){
 const unlocked=bonusUnlocked();
 $('#missionCards').innerHTML=D.missions.map((c,i)=>`<button class="missionCard ${!bonusActive&&i===selected?'selected':''}" data-mission="${i}"><span class="number">MISSION ${i+1}</span><h3>${esc(c.title)}</h3><p>${esc(c.patient.name)} · ${c.patient.age} Jahre<br>${esc(c.subtitle)}</p>${completed[c.id]?'<span class="finished">✓ Abgeschlossen</span>':''}</button>`).join('')+(unlocked?`<button class="missionCard" data-bonus-pub="true"><span class="number">ZUSATZMISSION 6</span><h3>Finde das GCB Pub</h3><p>Entdecke das Pub am Quai und tritt ein.</p>${bonusRecord?'<span class="finished">✓ Zusatzmission abgeschlossen</span>':'<span class="finished">Bonus freigeschaltet</span>'}</button>`:'');
 document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{selected=+b.dataset.mission;renderCards()});document.querySelectorAll('[data-bonus-pub]').forEach(b=>b.onclick=()=>beginBonus());
 $('#totalProgress').textContent=`${D.missions.filter(c=>completed[c.id]).length} von 5 abgeschlossen`;
 if(homeCaption)homeCaption.textContent=homeCaptionBase+(unlocked?' · Zusatzmission 6: GCB Pub über die Karte (M) finden':'');
}
function tutorial(start=false){if(bonusActive&&running){bonusJournal();return;}panel('SO SPIELST DU','Deine erste Transportmission',`<p>Du begleitest eine Person vom Auftrag bis zur Übergabe. Lies zuerst ihren Bedarf – dann suchst du das passende Fahrzeug in der Stadt.</p><div class="grid"><div class="card"><span class="introIcon">☏</span><h3>Gespräch und Vorbereitung</h3><p>Folge dem leuchtenden Abholpunkt. Drücke Enter bei der Person, stelle die drei Fragen und bereite die nötigen Dinge vor.</p></div><div class="card"><span class="introIcon">▰</span><h3>Fahrzeug finden</h3><p>Der Richtungspfeil oben zeigt den Weg zum aktuellen Ziel, daneben siehst du die Entfernung. Unten links siehst du die Karte mit allen fünf Fahrzeugen. M öffnet die Karte mit fünf Fahrzeugstandorten und ihren Namen. Gehe zu einem Wagen, prüfe sein Angebot mit Enter und steige ein.</p></div><div class="card"><span class="introIcon">⌖</span><h3>Abholen und fahren</h3><p>Fahre zurück zur Abholzone und halte an. Übernimm die Person mit Enter. Folge danach der Route zum Ziel.</p></div><div class="card"><span class="introIcon">✓</span><h3>Persönlich übergeben</h3><p>Am Ziel parkieren, mit F aussteigen und mit Enter die Übergabe prüfen. Fehler kannst du verbessern.</p></div></div>${bonusHelp()}<div class="info"><strong>Steuerung</strong><p>Pfeiltasten: ←/→ drehen Figur und Kamera, ↑ geht vorwärts, ↓ rückwärts. Drehen geht auch im Stand. Im Fahrzeug: lenken, Gas und Bremse. Enter: die angezeigte Aktion ausführen oder eine Schaltfläche bestätigen. In Dialogen wählst du Schaltflächen mit ↑/↓; Tab wechselt zu Auswahlfeldern, Leertaste wählt Kästchen an oder ab. Nach zwei Sekunden Vorwärtsgehen rennst du automatisch. Shift: sofort sprinten. Maus halten und ziehen: kurz umschauen; danach folgt die Kamera beim Weitergehen wieder der Figur. F: einmal drücken – anhalten und aussteigen. M: Karte. J: Auftrag. Esc: Pause. Zu Fuss: sichtbare Spielfigur. Im Auto: Aussenansicht von hinten. C richtet die Kamera wieder hinter dem Wagen aus. Auf der Karte findest du auch frei nutzbare Stadtwagen und E-Scooter für eigene Wege. Auf dem Scooter bleibt deine Figur sichtbar; Einmal F hält an und lässt dich absteigen. Patientinnen und Patienten fahren mit dem geprüften Transportangebot.</p></div><p class="small">Die Fahrsteuerung ist eine Spielabstraktion. Im Berufsalltag fahren entsprechend berechtigte Personen. Pflege, Verladung und Sicherung erfordern den vereinbarten Auftrag und die nötige Qualifikation. Beim Rettungswagen ist das qualifizierte Team an Bord. Geschwindigkeit gibt keine Lernpunkte.</p><div class="actions">${button(start?'Mission beginnen':'Verstanden',start?'begin':'close',String(selected))}</div>`);settings.tutorial=true;store()}
async function begin(index){if(loading||!Number.isInteger(index)||index<0||index>=D.missions.length)return;bonusActive=false;bonusReached=false;loading=true;const token=++loadToken;lastCitizen=chatCitizen=currentChat=null;await A?.unlock();if(token!==loadToken)return;A?.pauseMusic();stopVoice();selected=index;m=D.missions[index];s=R.newState(m.id);t=null;target=m.pickup;Drive.pause?.();panel('EINEN MOMENT','Deine Stadt wird vorbereitet.',`<p>Fahrzeuge und Figuren werden geladen. Danach kannst du die Mission ohne nachträglich aufploppende Modelle beginnen.</p><p role="status" id="loadingStatus">Fahrzeuge werden vorbereitet …</p>`);$('#closeDialog').hidden=true;await new Promise(requestAnimationFrame);try{await window.H3Vehicles?.preload?.();if(token!==loadToken)return;$('#loadingStatus').textContent='Die Stadt wird vorbereitet …';running=true;$('#home').hidden=true;$('#game').hidden=false;document.body.classList.add('playing');['journalBtn','mapBtn','pauseBtn'].forEach(id=>$('#'+id).hidden=false);Drive.init($('#city'),telemetry,onWorldAction);readyWorld=true;Drive.setQuality?.(settings.quality||'auto');Drive.setMission({id:m.id,pickup:m.pickup,dropoff:m.dropoff,patient:m.patient,vehicleType:m.vehicleType});$('#loadingStatus').textContent='Gleich geht es los …';await Drive.ready?.();if(token!==loadToken)return;Drive.setTarget(m.pickup);Drive.resize();loading=false;$('#closeDialog').hidden=false;modal.close();Drive.resume();A?.resumeMusic();update();missionBrief()}catch(e){if(token!==loadToken)return;running=false;loading=false;$('#closeDialog').hidden=false;panel('GRAFIKSTART','Die Stadt konnte nicht starten',`<p>${esc(e.message)}</p><p>Bitte einen aktuellen Desktop-Browser mit aktivierter Grafikbeschleunigung verwenden.</p><div class="actions">${button('Erneut versuchen','begin',String(index))}${button('Zur Missionsauswahl','home','','secondary')}</div>`);console.error(e)}}
function navigate(p){target=p;mapPaintAt=0;Drive.setTarget(p);update();drawMap($('#miniMap'))}
function setText(selector,value){const e=$(selector),v=String(value);if(e.textContent!==v)e.textContent=v}
let mapPaintAt=0;
function telemetry(info){const served=info.pubOrderState==='served'&&t?.pubOrderState!=='served';t=info;if(served){const meal=pubMeals.find(q=>q.id===info.pubOrderItem);toast('Kellner: «Bitte sehr! '+(meal?.name||'Dein Gericht')+' steht auf dem Tresen. Guten Appetit!»');}if(target?.id&&target.id===info.targetId){target.x=info.targetX;target.z=info.targetZ;}$('#exitBtn').disabled=!!info.exitPending;$('#contextBtn').disabled=!!info.exitPending||!!info.enterPending;A?.updateVehicle?.(info);if(info.nearCitizen)lastCitizen={...info.nearCitizen,seenAt:Date.now()};if(info.error){++loadToken;loading=false;running=false;$('#closeDialog').hidden=false;Drive.pause();A?.pauseMusic();panel('GRAFIK','Darstellung unterbrochen',`<p>${esc(info.error)}</p>${button('Zur Missionsauswahl','home')}`);return}setText('#speed',Math.round(info.speed||0));setText('#travelMode',info.mode==='car'?info.vehicleName||'IM FAHRZEUG':'ZU FUSS');$('#exitBtn').hidden=info.mode!=='car';const exitLabel=info.vehicleKind==='scooter'?'Absteigen':'Aussteigen';if($('#exitBtn').dataset.kind!==exitLabel){$('#exitBtn').dataset.kind=exitLabel;$('#exitBtn').innerHTML=exitLabel+' <kbd>F</kbd>';}$('#vehicleHud').hidden=info.mode!=='car';updateGuidance(info);const mapNow=Date.now();if(mapNow-mapPaintAt>=100){drawMap($('#miniMap'));mapPaintAt=mapNow}updateContext();completeBonusIfInside(info)}
let guideAngle=0,guideKey='';
function updateGuidance(info){const box=$('#routeGuide');if(!box)return;const g=info.guidance;box.hidden=!running||!target||!!s?.finished;if(box.hidden){guideKey='';return}const nextAngle=Number.isFinite(g?.angle)?g.angle:0,key=[bonusActive?'bonus-pub':m.id,target.x,target.z,info.mode,info.vehicleId||''].join('/');const arrow=$('#routeArrow'),changed=guideKey!==key;if(changed){guideKey=key;guideAngle=nextAngle;arrow.style.transition='none';requestAnimationFrame(()=>{if(guideKey===key)arrow.style.transition=''})}else guideAngle+=Math.atan2(Math.sin(nextAngle-guideAngle),Math.cos(nextAngle-guideAngle));arrow.style.transform='rotate('+guideAngle+'rad)';if(changed)arrow.getBoundingClientRect?.();$('#routeDestination').textContent=target.label||'Markiertes Ziel';$('#routeRemaining').textContent=Math.round(g?.distance??info.distance??0)+' m';box.classList.toggle('arrived',!!g?.arrived);box.setAttribute('aria-label',`${g?.arrived?'Zielbereich erreicht. ':''}${target.label||'Markiertes Ziel'}, ${Math.round(g?.distance??info.distance??0)} Meter`)}
function phase(){if(s.finished)return 5;if(s.loaded)return 4;if(s.prepared&&s.approved)return 3;if(s.prepared)return 2;if(s.asked.length>=m.dialogue.length)return 1;return 0}
const phaseTexts=[['Lerne die Person kennen.','Finde den Abholort und kläre Mobilität, Wünsche und Vereinbarungen im Gespräch.'],['Bereite die Fahrt vor.','Stelle die benötigten Dinge bereit und bestätige Begleitung und Kostenregelung.'],['Finde das passende Fahrzeug.','Die Karte zeigt die Standorte. Prüfe das konkrete Fahrzeugangebot vor Ort.'],['Zurück zur Abholung.','Komm mit dem geprüften Fahrzeug zur Abholzone, halte an und übernimm die Person.'],['Bring die Person ans Ziel.','Fahre ruhig zur markierten Zielstelle. Parkiere, steige aus und prüfe die Übergabe.'],['Mission abgeschlossen.','Dein Bericht steht im Journal bereit.']];
function progressSteps(){const p=phase();return '<div class="steps">'+['Gespräch','Vorbereitung','Fahrzeug','Abholung','Übergabe'].map((v,i)=>`<span class="step ${i<p?'done':i===p?'current':''}">${i<p?'✓ ':''}${v}</span>`).join('')+'</div>'}
function update(){if(bonusActive){$('#missionTag').textContent='ZUSATZMISSION 6';$('#objectiveTitle').textContent=bonusReached?'GCB Pub gefunden':'Finde das GCB Pub.';$('#objectiveBtn').setAttribute('aria-label','Zusatzauftrag öffnen: Finde das GCB Pub am Quai und tritt ein.');updateContext();return;}if(!s)return;const p=phase();$('#missionTag').textContent=`MISSION ${selected+1} · ${m.patient.name}`;$('#objectiveTitle').textContent=phaseTexts[p][0];$('#objectiveBtn').setAttribute('aria-label',`Auftrag für ${m.patient.name} öffnen: ${phaseTexts[p][0]} ${phaseTexts[p][1]}`);updateContext()}

function allVehicles(){return [...(t?.cars||[]),...(t?.mobility||[])];}
function pickupAction(){
 if(t.civilVehicle)return {label:'Eigenes Fahrzeug ansehen',run:()=>vehiclePanel(t.vehicleId)};
 if(!s.prepared)return s.asked.length<m.dialogue.length?{label:'Gespräch vervollständigen',run:patientPanel}:{label:'Vorbereitung prüfen',run:packPanel};
 if(!s.approved||s.approved.id!==t.vehicleId)return {label:'Fahrzeugangebot prüfen',run:()=>vehiclePanel(t.vehicleId)};
 return {label:t.stationary?'Person übernehmen':'Zur Übernahme anhalten',run:board};
}
function transportAction(){
 const atHandover=t.dropoffDistance<=12&&(t.mode==='car'||Math.hypot(t.x-m.dropoff.x,t.z-m.dropoff.z)<=12);
 if(atHandover)return {label:t.mode==='car'?'Am Ziel übergeben':'Übergabe öffnen',run:handover};
 if(t.mode==='walk'){
  const id=s.approved?.id||t.vehicleId;
  if(t.nearVehicle?.id===id)return {label:'Wieder einsteigen',run:()=>enter(id)};
  return {label:'Zum Fahrzeug zurück',run:()=>navVehicle(id)};
 }
 return {label:'Transportauftrag ansehen',run:journal};
}
function updateContext(){if(!t)return;if(bonusActive){$('#contextBtn span').textContent=bonusContextLabel();return;}if(!s)return;let label='Auftrag ansehen';if(t.exitPending)label='Wird angehalten …';else if(t.enterPending)label='Wagen hält an …';else if(t.nearPubCounter)label=t.pubOrderState==='preparing'?'Dein Gericht wird zubereitet …':'Beim Kellner bestellen';else if(s.finished)label='Auswertung ansehen';else if(s.loaded)label=transportAction().label;else if(t.mode==='car')label=t.civilVehicle?(t.vehicleKind==='scooter'?'Absteigen':'Aussteigen'):t.pickupDistance<=12?pickupAction().label:'Fahrzeug prüfen';else if(t.nearPatient)label='Mit '+m.patient.name+' sprechen';else if(t.nearVehicle)label=t.nearVehicle.name+' ansehen';else if(t.nearCitizen)label='Passantin oder Passanten ansprechen';$('#contextBtn span').textContent=label}
function context(){if(!running||modal.open||!t)return;if(t.exitPending||t.enterPending)return;if(t.nearPubCounter){pubPanel();return;}if(bonusActive){if(t.mode==='car')exit();else if(t.nearVehicle)vehiclePanel(t.nearVehicle.id);else if(t.nearCitizen)citizenPanel();else bonusJournal();return;}if(s.finished){report();return}if(s.loaded){transportAction().run();return}if(t.mode==='car'&&t.civilVehicle){exit();return}if(t.mode==='car'&&t.pickupDistance<=12){pickupAction().run();return}if(t.mode==='car'){vehiclePanel(t.vehicleId);return}if(t.nearPatient){patientPanel();return}if(t.nearVehicle){vehiclePanel(t.nearVehicle.id);return}if(t.nearCitizen){citizenPanel();return}if(lastCitizen&&Date.now()-lastCitizen.seenAt<1600&&Math.hypot(t.x-lastCitizen.x,t.z-lastCitizen.z)<5){citizenPanel(lastCitizen);return}journal()}
function onWorldAction(e){if(!running||modal.open)return;if(e.kind==='pub-order'){pubPanel();return;}if(e.kind==='exit'){toast(e.status==='exited'?'Du bist ausgestiegen.':'Hier ist der Ausstieg blockiert. Stelle das Fahrzeug etwas freier ab.');return}if(e.kind==='enter'){toast(e.status==='entered'?'Du kannst losfahren.':'Der Wagen hält an. Gehe an die Tür und drücke Enter.');return}if(bonusActive){if(e.kind==='vehicle')vehiclePanel(e.vehicleId);else if(e.kind==='collision')toast('Berührung: Halte an und prüfe den freien Weg.');return;}if(s.finished){report();return}if(e.kind==='collision'){s.collisions++;toast('Berührung: anhalten und den freien Weg prüfen. Ruhiges Fahren zählt.');return}if(s.loaded&&['vehicle','patient','destination'].includes(e.kind)){transportAction().run();return}if(e.kind==='vehicle')vehiclePanel(e.vehicleId);else if(e.kind==='patient'){if(t.mode==='car'&&t.pickupDistance<=12)pickupAction().run();else patientPanel()}else if(e.kind==='destination')handover()}
function citizenPanel(person=t?.nearCitizen){if(t?.mode!=='walk'||!person)return;const nearby=t.nearCitizen?.id===person.id||lastCitizen?.id===person.id&&Date.now()-lastCitizen.seenAt<1600&&Math.hypot(t.x-person.x,t.z-person.z)<5;if(!nearby&&chatCitizen!==person){toast('Gehe etwas näher zur Person.');return}chatCitizen=person;currentChat=window.H3Chats?.next(person.id,person.sex);if(!currentChat)return;const line=currentChat;panel('BEGEGNUNG IN DER STADT',line.name,`<p class="small">Du: «${esc(line.question)}»</p><div class="quote">«${esc(line.text)}»</div><div class="actions">${button('Weiterplaudern','chatmore')}${button('Nochmals hören','chatreplay','','secondary')}${button('Danke, weitergehen','close','','secondary')}</div>`);if(settings.sound)A?.speak(line.key,line.text,{sex:line.sex})}
function patientPanel(){if(!t||(s.loaded||s.finished)||!(t.nearPatient||t.mode==='car'&&t.pickupDistance<=12)){toast(s.loaded?'Die Person ist bereits übernommen. Nutze den Auftrag für die vereinbarten Angaben.':'Gehe zur Person am Abholort, um das Gespräch zu führen.');return}panel('GESPRÄCH UND AUFTRAG',m.patient.name,`<p>${m.patient.age} Jahre · ${esc(m.pickup.label)}</p><div class="quote">«${esc(m.patient.quote)}»</div>${m.dialogue.map(q=>`<button class="question ${s.asked.includes(q.id)?'asked':''}" data-action="ask" data-id="${q.id}">${s.asked.includes(q.id)?'✓ ':''}${esc(q.question)}</button>`).join('')}<div id="answer"></div><div class="actions">${button('Vorbereitung prüfen','pack')}${t.mode==='car'?button('Fahrzeugangebot prüfen','vehicle',String(t.vehicleId),'secondary'):''}${s.prepared&&s.approved?button('Person übernehmen','board','','gold'):''}${button('Auftrag ansehen','journal','','secondary')}</div>`,true);Drive.portrait?.('patient');if(!s.patientIntroShown){s.patientIntroShown=true;speak('intro',m.patient.quote)}}
function ask(id){const q=m.dialogue.find(q=>q.id===id);if(!q)return;if(!s.asked.includes(id))s.asked.push(id);s.answers[id]=q.answer;update();body.querySelectorAll('.question').forEach(b=>{if(b.dataset.id===id){b.classList.add('asked');b.textContent='✓ '+q.question}});$('#answer').innerHTML=`<div class="answer"><strong>${esc(m.patient.name)}</strong><p>«${esc(q.answer)}»</p>${button('Nochmals hören','replay',id,'secondary')}</div>`;bind();$('#answer').scrollIntoView({block:'nearest'});speak(id,q.answer)}
function packPanel(){if(s.loaded||s.finished){panel('VORBEREITUNG AN BORD','Das ist vorbereitet.',`<p>Die Person und die bestätigten Dinge sind bereits im Fahrzeug.</p><div class="info">${m.packOptions.filter(o=>s.pack.includes(o.id)).map(o=>esc(o.label)).join('<br>')}</div><p>${esc(m.escort)}</p><p>${esc(m.costs)}</p><div class="actions">${button('Zur Stadt','close')}</div>`);return}panel('VORBEREITUNG','Was kommt mit?',`<p>Bereite nur fallbezogen benötigte oder ausdrücklich gewünschte Dinge vor. Kleidung wird bereitgelegt oder angezogen, Hilfsmittel werden separat mitgegeben.</p><form id="prepForm">${m.packOptions.map(o=>`<label class="check"><input type="checkbox" name="item" value="${o.id}" ${s.pack.includes(o.id)?'checked':''}><span>${esc(o.label)}</span></label>`).join('')}<div class="info"><strong>Unterstützung und Begleitung</strong><p>${esc(m.escort)}</p><p><strong>Rückweg:</strong> ${esc(m.returnPlan)}</p></div><label class="check"><input type="checkbox" name="escort" ${s.escort?'checked':''}><span>Ich habe die genannte Vereinbarung geprüft; Unterstützung und Begleitung sind tatsächlich gesichert.</span></label><div class="info"><strong>Kostenregelung dieses Falls</strong><p>${esc(m.costs)}</p></div><label class="check"><input type="checkbox" name="costs" ${s.costs?'checked':''}><span>Die Kostenregelung ist für diesen Auftrag geklärt; ich leite daraus keine pauschale Versicherungsdeckung ab.</span></label><div id="prepFeedback"></div><div class="actions"><button class="primary" type="submit">Vorbereitung bestätigen</button>${button('Zurück zum Gespräch','patient','','secondary')}</div></form>`);body.querySelector('[data-action="patient"]').onclick=patientPanel;$('#prepForm').onchange=()=>{const f=new FormData($('#prepForm'));s.pack=f.getAll('item');s.escort=f.has('escort');s.costs=f.has('costs');s.prepared=false;update()};$('#prepForm').onsubmit=e=>{e.preventDefault();prepare()}}
function prepare(){const f=new FormData($('#prepForm'));s.pack=f.getAll('item');s.escort=f.has('escort');s.costs=f.has('costs');const errors=R.prepIssues(m,s);if(errors.length){$('#prepFeedback').innerHTML=`<div class="info warning"><strong>Noch klären</strong><p>${errors.map(esc).join('<br><br>')}</p></div>`;$('#prepFeedback').scrollIntoView({block:'nearest'});return}s.prepared=true;update();const inApproved=t.mode==='car'&&!t.civilVehicle&&String(t.vehicleId)===String(s.approved?.id);if(s.approved){const v=t.cars.find(v=>v.id===s.approved.id);navigate(inApproved?m.pickup:v?{...v,label:v.name}:m.pickup)}else{const nearest=t.cars.reduce((a,b)=>Math.hypot(b.x-t.x,b.z-t.z)<Math.hypot(a.x-t.x,a.z-t.z)?b:a);navigate({...nearest,label:nearest.name+' · Angebot prüfen'})}panel('VORBEREITUNG BESTÄTIGT','Die Person ist vorbereitet.',`<p>Die nötigen Dinge und Vereinbarungen sind gesichert. ${s.approved?(inApproved?'Die Weganzeige führt mit dem geprüften Fahrzeug zurück zur Abholung.':'Die Weganzeige führt zurück zum bereits geprüften Fahrzeug.'):'Die Weganzeige führt zum nächstgelegenen Fahrzeugangebot. Prüfe selbst, ob seine Leistungen passen. Auf der Karte kannst du ein anderes Fahrzeug als Suchziel wählen.'}</p><div class="actions">${button('Fahrzeuge auf der Karte','map')}${button('Zur Stadt','close','','secondary')}</div>`)}
function vehiclePanel(id){const v=allVehicles().find(v=>String(v.id)===String(id));if(!v){toast('Dieses Fahrzeug ist nicht erreichbar. Gehe näher heran.');return}if(bonusActive){const aboard=t.mode==='car'&&String(t.vehicleId)===String(v.id),scooter=v.kind==='scooter';panel('FREI UNTERWEGS',v.name,`<p>${scooter?'Mit dem E-Scooter kannst du den Quai erkunden.':'Nutze diesen Wagen für deine Entdeckungstour durch Lindenhafen.'}</p><div class="actions">${aboard?button(scooter?'Absteigen':'Aussteigen','exit'):button(scooter?'Aufsteigen':'Einsteigen','enter',String(v.id))}${button('Zusatzauftrag','bonusjournal','','secondary')}${button('Zur Stadt','close','','secondary')}</div>`);return;}if(v.civil){const aboard=t.mode==='car'&&String(t.vehicleId)===String(v.id),scooter=v.kind==='scooter';panel('FREI UNTERWEGS',v.name,`<p>${scooter?'Nutze den E-Scooter für eigene Wege durch Lindenhafen. Er fährt höchstens 20 km/h.':'Mit diesem Stadtwagen kannst du eigene Wege durch Lindenhafen zurücklegen.'}</p><div class="info">Die Person deines Transportauftrags bleibt am vereinbarten Ort. Für ihren Transport brauchst du das konkret geprüfte Transportfahrzeug.</div><div class="actions">${aboard?button(scooter?'Absteigen':'Aussteigen','exit'):button(scooter?'Aufsteigen':'Einsteigen','enter',String(v.id))}${button('Zum Abholort','navpickup','','secondary')}${button('Auftrag ansehen','journal','','secondary')}${button('Zur Stadt','close','','secondary')}</div>`);return}const offer=D.offers.find(o=>o.id===v.type);panel('FAHRZEUG VOR ORT',v.name||offer?.label||'Transportfahrzeug',`<div class="info"><strong>${esc(offer?.label)}</strong><p>${esc(offer?.offer)}</p></div><p class="small">Dieses Angebot gilt für den fiktiven Auftrag. Prüfe es am konkreten Bedarf der Person.</p><form id="vehicleForm"><h3>${esc(m.check.question)}</h3>${m.check.options.map(o=>`<label class="check"><input type="radio" name="reason" value="${o.id}" ${s.reason===o.id?'checked':''}><span>${esc(o.label)}</span></label>`).join('')}<div id="vehicleFeedback"></div><div class="actions"><button class="primary" type="submit">Für den Auftrag prüfen</button>${t.mode==='walk'?button('Einsteigen','enter',String(v.id),'secondary'):button('Aussteigen','exit','','secondary')}${button('Fallangaben lesen','journal','','secondary')}</div></form>`);$('#vehicleForm').onsubmit=e=>{e.preventDefault();approveVehicle(v.id)}}
function approveVehicle(id){const v=t.cars.find(v=>String(v.id)===String(id));if(!v){toast('Prüfe ein Transportfahrzeug für diesen Auftrag.');return}const f=new FormData($('#vehicleForm')),reason=f.get('reason');const errors=R.vehicleIssues(m,v.type,reason);if(errors.length){$('#vehicleFeedback').innerHTML=`<div class="info warning"><p>${errors.map(esc).join('<br><br>')}</p></div>`;$('#vehicleFeedback').scrollIntoView({block:'nearest'});return}s.reason=reason;s.approved={id:v.id,type:v.type};update();panel('FAHRZEUG BESTÄTIGT','Das Angebot passt zum Auftrag.',`<div class="info">${esc(m.vehicleReason)}</div><p>Das konkrete Fahrzeug ist für diesen Auftrag bestätigt. ${s.prepared?'Fahre zur Abholung.':'Kläre noch das Gespräch und die Vorbereitung am Abholort.'}</p><div class="actions">${button(t.mode==='car'?'Zur Abholung fahren':'Einsteigen',t.mode==='car'?'navpickup':'enter',String(v.id))}${button('Zur Stadt','close','','secondary')}</div>`);navigate(m.pickup)}
function enter(id){if(s?.loaded&&String(t.vehicleId)!==String(id)){toast('Die Person bleibt im bestätigten Fahrzeug. Wechsle jetzt nicht den Wagen.');return}closePanel();const result=Drive.requestEnter?Drive.requestEnter(id):(Drive.enterVehicle(id)?'entered':'unavailable');if(result==='entered'){if(s?.approved&&String(s.approved.id)===String(id))navigate(s.loaded?m.dropoff:m.pickup);toast('Pfeiltasten steuern. Einmal F: anhalten und aussteigen.')}else toast(result==='waiting'?'Der Wagen hält für dich an.':'Gehe näher an das Fahrzeug heran.')}
function exit(){if(t?.exitPending)return;closePanel();const result=Drive.requestExit?Drive.requestExit():(Drive.exitVehicle()?'exited':'blocked');toast(result==='exited'?'Du bist ausgestiegen. Pfeiltasten bewegen dich.':result==='braking'?'Das Fahrzeug hält an; danach steigst du automatisch aus.':'Hier ist der Ausstieg blockiert. Stelle das Fahrzeug etwas freier ab.')}

function board(){const errors=R.boardIssues(m,s,t);if(errors.length){panel('ÜBERNAHME NOCH OFFEN','Die Person wartet noch.',`<div class="info warning">${errors.map(esc).join('<br><br>')}</div><div class="actions">${button('Auftrag prüfen','journal')}${button('Zur Stadt','close','','secondary')}</div>`);return}if(!Drive.loadPatient()){toast('Übernahme noch nicht möglich. Fahrzeug, Abstand und Stillstand prüfen.');return}s.loaded=true;s.delivered=false;navigate(m.dropoff);update();panel('PERSON ÜBERNOMMEN','Die Fahrt kann beginnen.',`<div class="info"><strong>${esc(m.patient.name)}</strong><p>${esc(m.transportOrder)}</p><p>${esc(m.escort)}</p></div><p>Die Übernahme und Sicherung durch die zuständigen Personen ist im Spiel bestätigt. Du steuerst die Fahrt als abstrahierte Simulation; es ist keine praktische Sicherungsprüfung.</p><div class="actions">${button('Zum Ziel fahren','close')}</div>`)}
function handover(){if(!s.loaded){toast('Hole zuerst die vorbereitete Person mit dem bestätigten Fahrzeug ab.');return}if(t.dropoffDistance>12){toast('Das Ziel ist noch nicht erreicht. Folge der markierten Route.');return}if(t.mode==='walk'&&Math.hypot(t.x-m.dropoff.x,t.z-m.dropoff.z)>12){navigate(m.dropoff);toast('Gehe zur Person in der Übergabezone zurück. Die persönliche Übergabe findet vor Ort statt.');return}if(t.mode==='car'){panel('AM ZIEL','Parkieren und aussteigen',`<p>Halte an der Abhol- beziehungsweise Übergabezone und steige aus. Danach prüfst du die persönliche Übergabe.</p><div class="actions">${button('Anhalten und aussteigen','exit')}${button('Zur Fahrt','close','','secondary')}</div>`);return}panel('PERSÖNLICHE ÜBERGABE',m.dropoff.label,`<p>${esc(m.patient.name)} ist angekommen. Wähle nur die nötigen Übergabeinformationen.</p><form id="handoverForm">${m.handover.map(h=>`<label class="check"><input type="checkbox" name="handover" value="${h.id}"><span>${esc(h.label)}</span></label>`).join('')}<div id="handoverFeedback"></div><div class="actions"><button class="primary" type="submit">Übergeben und abschliessen</button></div></form>`);$('#handoverForm').onsubmit=e=>{e.preventDefault();finish()}}
function finish(){if(s.finished){report();return}s.attempts++;const checked=new FormData($('#handoverForm')).getAll('handover');const errors=R.handoverIssues(m,s,t,checked);if(errors.length){$('#handoverFeedback').innerHTML=`<div class="info warning">${errors.map(esc).join('<br><br>')}</div>`;$('#handoverFeedback').scrollIntoView({block:'nearest'});return}if(!Drive.unloadPatient()){toast('Die Übergabezone ist noch nicht bereit. Prüfe Stillstand und Abstand.');return}s.delivered=true;s.loaded=false;s.finished=true;target=null;completed[m.id]={id:m.id,name:m.patient.name,vehicle:s.approved.type,prepared:s.pack,collisions:s.collisions,reason:s.reason,finished:new Date().toISOString()};store();update();updateGuidance(t);report()}
function report(){if(bonusActive){bonusJournal();return;}panel('MISSION ABGESCHLOSSEN','Gut vorbereitet. Sicher angekommen.',`<div class="info"><strong>${esc(m.patient.name)} · ${esc(m.dropoff.label)}</strong><p>${esc(m.vehicleReason)}</p></div><div class="feedbackRow"><strong>Gespräch und Vorbereitung</strong>Bedarf und Wünsche erhoben; nötige Dinge und Vereinbarungen vorbereitet.</div><div class="feedbackRow"><strong>Fahrzeug und Route</strong>Konkretes Angebot geprüft, Person am richtigen Ort aufgenommen und tatsächlich zum Ziel gefahren.</div><div class="feedbackRow"><strong>Übergabe</strong>Notwendige Angaben ausgewählt; private Angaben ohne Transportbezug geschützt.</div><p class="small" style="margin-top:16px">${s.collisions?`${s.collisions} Berührung(en) im Spiel: Überlege, wo ruhigeres Fahren oder eine andere Linie geholfen hätte.`:'Ohne registrierte Fahrzeugberührung angekommen.'} Fahrgeschick ist keine FaGe-Kompetenznote.</p><h3 style="margin-top:20px">Für deine OneNote-Seite</h3><p>${esc(m.finishReflection)}</p>${bonusUnlocked()?`<div class="info"><strong>Zusatzmission 6 freigeschaltet</strong><p>Alle fünf Transportmissionen sind abgeschlossen. Finde jetzt das GCB Pub am Quai.</p>${button('Zusatzmission starten','beginbonus')}</div>`:''}<div class="actions">${button('Bericht herunterladen','export')}${selected<4?button('Nächste Mission','next','','secondary'):''}${button('Missionsauswahl','home','','secondary')}</div>`)}
function journal(){if(bonusActive&&running){bonusJournal();return;}if(!running){tutorial(false);return}if(s.finished){report();return}panel('AUFTRAGSJOURNAL',m.title,`<div class="info"><strong>${esc(phaseTexts[phase()][0])}</strong><p>${esc(phaseTexts[phase()][1])}</p></div>${progressSteps()}<div class="tabs">${button('Gespräch','patient','','secondary')}${button('Vorbereitung','pack','','secondary')}${button('Karte','map','','secondary')}</div>${[['Person',m.patient.name+' · '+m.patient.age+' Jahre'],['Von / Nach',m.pickup.label+' / '+m.dropoff.label],['Termin und Abholung',m.appointmentTime+' · Abholung '+m.pickupTime],['Ausgangslage',m.condition],['Mobilität',m.mobility],['Transportauftrag',m.transportOrder],['Begleitung',m.escort],['Rückweg',m.returnPlan],['Kostenregelung',m.costs]].map(([key,value])=>`<div class="dataRow"><b>${esc(key)}</b>${esc(value)}</div>`).join('')}<div class="actions">${button('Lehrmittel und Hinweise','sources','','secondary')}${button('Zur Stadt','close')}</div>`);body.querySelector('[data-action="patient"]').onclick=()=>{if(t.nearPatient||t.mode==='car'&&t.pickupDistance<=12)patientPanel();else toast('Gehe zur Person am Abholort, um das Gespräch zu führen.')}}
function navVehicle(id){const v=allVehicles().find(v=>String(v.id)===String(id));if(v){navigate({...v,label:v.name});closePanel();toast(v.name+' ist als Suchziel markiert.')}}
function mapPanel(){
 if(!running)return;const unlocked=bonusUnlocked();
 panel('NAVIGATION','Dein Weg durch Lindenhafen',`<canvas id="dialogMap" width="760" height="410" aria-label="Stadtplan mit Strassen, Fahrzeugen, ${unlocked?'GCB Pub, ':''}Person und Ziel"></canvas><p class="small">Weiss: du${bonusActive?'':' · Rosa: Abholort'} · Gold: Ziel · Türkis 1–5: Transportfahrzeuge · Blau: Stadtwagen · Violett: E-Scooter${unlocked?' · Goldenes G: GCB Pub':''}. Norden bleibt oben. Die Linie folgt den Strassen. Auf der Karte wird niemand teleportiert.</p>${unlocked?`<h3>Orte in der Stadt</h3><div class="actions">${button('GCB Pub finden','navpub','','secondary')}</div>`:''}<h3>Fahrzeug als Suchziel markieren</h3><div class="vehicleList">${t.cars.map((v,index)=>`<button data-action="navvehicle" data-id="${esc(v.id)}">${index+1}. ${esc(v.name)}<small>${bonusActive?'Für deine Wege durch Lindenhafen':esc(D.offers.find(o=>o.id===v.type)?.short||'Fahrzeug ansehen')}</small></button>`).join('')}</div>${(t.mobility||[]).length?`<h3>Fahrzeuge für deine eigenen Wege</h3><div class="vehicleList">${t.mobility.map(v=>`<button data-action="navvehicle" data-id="${esc(v.id)}">${esc(v.name)}<small>${v.kind==='scooter'?'E-Scooter · 20 km/h':v.traffic?'Stadtwagen · hält in deiner Nähe an':'Stadtwagen · frei nutzbar'}</small></button>`).join('')}</div>`:''}<div class="actions">${bonusActive?button('Zusatzauftrag','bonusjournal','','secondary'):button(s?.loaded?'Zum Übergabeort':'Zum Abholort',s?.loaded?'navdrop':'navpickup','','secondary')}${button('Zur Stadt','close')}</div>`);
 if(!bonusActive&&s?.loaded)body.querySelector('[data-action="navdrop"]').onclick=()=>{navigate(m.dropoff);closePanel()};drawMap($('#dialogMap'));
}
function drawMap(c){
 if(!c||!t)return;
 const g=c.getContext('2d'),w=c.width,h=c.height,mini=c.id==='miniMap',scale=Math.min(w/228,h/220),ox=w/2,oy=h/2;
 g.fillStyle='#122835';g.fillRect(0,0,w,h);
 const p=(x,z)=>[ox+x*scale,oy+z*scale],rect=(x,z,dx,dz,col)=>{g.fillStyle=col;g.fillRect(...p(x,z),dx*scale,dz*scale)};
 rect(-103,-103,207,206,'#39504e');rect(-113,-103,10,206,'#2d6c81');
 for(const x of [-80,-24,32,88])rect(x-6,-102,12,204,'#7a8584');for(const z of [-84,-28,28,84])rect(-99,z-6,199,12,'#7a8584');
 // The HUD and both maps consume the same retained route, including its live
 // start position. No independent map-side projection can choose another leg.
 const path=target?t.guidance?.path:null;
 if(path?.length){g.strokeStyle='#ffd08d';g.lineWidth=mini?2.5:4;g.lineJoin='round';g.beginPath();path.forEach((q,i)=>g[i?'lineTo':'moveTo'](...p(q.x,q.z)));g.stroke()}
 const dot=(v,size,col)=>{g.fillStyle=col;g.beginPath();g.arc(...p(v.x,v.z),size,0,Math.PI*2);g.fill()};
 if(!bonusActive){dot(m.pickup,mini?3:5,'#f4a3c6');dot(m.dropoff,mini?3:5,'#ffd08d');}
 if(target){const [x,y]=p(target.x,target.z);g.strokeStyle='#fff0ba';g.lineWidth=mini?1.5:2;g.beginPath();g.arc(x,y,mini?6:10,0,Math.PI*2);g.stroke()}
 // Every vehicle uses the same neutral marker, regardless of the case answer.
 for(const v of t.mobility||[]){const[x,y]=p(v.x,v.z);g.beginPath();g.arc(x,y,mini?3:5,0,Math.PI*2);g.fillStyle=v.kind==='scooter'?'#c4a2ef':'#7abaf5';g.fill();g.strokeStyle='#142635';g.lineWidth=1;g.stroke();if(!mini){g.fillStyle='#f1f8ff';g.font='bold 11px Arial';g.fillText(v.kind==='scooter'?'S':'P',x+7,y+4)}}
 for(let index=0;index<t.cars.length;index++){const v=t.cars[index],[x,y]=p(v.x,v.z);g.fillStyle='#9cead9';g.strokeStyle='#0b242a';g.lineWidth=1.5;g.fillRect(x-3.5,y-4.5,7,9);g.strokeRect(x-3.5,y-4.5,7,9);g.font=mini?'bold 11px Arial':'bold 13px Arial';g.lineWidth=3;g.strokeStyle='#102835';g.strokeText(String(index+1),x+5,y-5);g.fillStyle='#e6fff5';g.fillText(String(index+1),x+5,y-5)}
 if(bonusUnlocked()){const [px,py]=p(pubPlace.x,pubPlace.z);g.fillStyle='#d5b978';g.beginPath();g.arc(px,py,mini?7:9,0,Math.PI*2);g.fill();g.fillStyle='#102c25';g.font='bold 14px Arial';g.textAlign='center';g.textBaseline='middle';g.fillText('G',px,py+.5);g.textAlign='left';g.textBaseline='alphabetic';
 if(!mini){g.fillStyle='#f3d998';g.font='bold 14px Arial';g.fillText('GCB Pub',px+13,py+4)}}
 const a=p(t.x,t.z);g.save();g.translate(...a);g.rotate(t.heading||0);g.beginPath();g.moveTo(0,-7);g.lineTo(5,6);g.lineTo(0,3);g.lineTo(-5,6);g.closePath();g.strokeStyle='#102835';g.lineWidth=2;g.stroke();g.fillStyle='white';g.fill();g.restore();
 g.fillStyle='#e8fff5';g.font='bold 13px Arial';g.fillText('N',8,17);
 if(mini&&bonusUnlocked()){g.fillStyle='#102835e8';g.fillRect(w-69,h-24,64,20);g.fillStyle='#f3d998';g.font='bold 14px Arial';g.fillText('G · Pub',w-64,h-9)}
}

function pause(){if(!running)return;if(bonusActive){panel('ZUSATZMISSION PAUSIERT','Deine Entdeckung wartet.',`<div class="actions">${button('Weiter erkunden','bonuscontinue')}${button('Zusatzauftrag','bonusjournal','','secondary')}${button('Karte','map','','secondary')}${button('Transportauswahl','home','','secondary')}</div>`);return;}A?.pauseMusic();panel('DIENST PAUSIERT','Deine Mission wartet.',`<p>Der laufende Auftrag bleibt während dieser Pause erhalten. Abgeschlossene Missionen werden in diesem Browser gespeichert.</p><div class="actions">${button('Weiterspielen','close')}${button('Auftrag lesen','journal','','secondary')}${button('Karte','map','','secondary')}${button('Mission verlassen','confirmhome','','secondary')}</div>`);body.querySelector('[data-action="confirmhome"]').onclick=()=>panel('MISSION VERLASSEN','Zurück zur Auswahl?',`<p>Die laufende Mission beginnt beim nächsten Start neu. Abgeschlossene Missionen bleiben gespeichert.</p><div class="actions">${button('Zur Auswahl','home')}${button('Weiterspielen','close','','secondary')}</div>`)}
function home(){bonusActive=false;bonusReached=false;target=null;A?.pauseMusic();A?.updateVehicle?.(null);A?.setScenePaused?.(false);++loadToken;loading=false;$('#closeDialog').hidden=false;A?.pauseMusic();stopVoice();Drive.pause?.();running=false;modal.close();$('#home').hidden=false;$('#game').hidden=true;document.body.classList.remove('playing');['journalBtn','mapBtn','pauseBtn'].forEach(id=>$('#'+id).hidden=true);renderCards();requestAnimationFrame(()=>window.drawCover?.($('#cover')))}
function sources(){panel('H3 TRANSPORTE','Lehrmittel und Lernrahmen',`<p>FaGe 3. Semester · H3 Transporte organisieren. Dieses Spiel übt Entscheidung, Vorbereitung und Kommunikation. Verladung, Sicherung und medizinische Betreuung werden als bestätigte Teamhandlungen abstrahiert.</p>${m.sources.map(q=>`<div class="dataRow"><a href="${esc(q.url)}" target="_blank" rel="noopener">${esc(q.title)}</a><p class="small">${esc(q.status)}</p></div>`).join('')}<p class="small" style="margin-top:16px">Alle Personen, Dienstangebote und Orte sind fiktiv. Keine reale Buchung, keine Spielkonten und keine Ergebnisübertragung an Lehrpersonen. Grafik: eigene Stadt und Bildarbeit, Three.js/Sketchbook MIT sowie CC0-Fahrzeuge, Menschen und einzelne Oberflächen; Nachweise im Spielpaket.</p><div class="actions">${button('Zurück','close')}</div>`)}
function exportReport(){const record=completed[m.id]||s;const text=['GTA · GESUNDHEIT. TRANSPORT. ABENTEUER.',m.title,m.patient.name+' (fiktiv)',`Abholort: ${m.pickup.label}`,`Ziel: ${m.dropoff.label}`,`Termin: ${m.appointmentTime} · Abholung: ${m.pickupTime}`,`Begleitung: ${m.escort}`,`Rückweg: ${m.returnPlan}`,`Fahrzeug: ${D.offers.find(v=>v.id===m.vehicleType)?.label}`,`Fallhinweis: ${m.vehicleReason}`,`Vorbereitet: ${m.packOptions.filter(p=>(record.prepared||s.pack).includes(p.id)).map(p=>p.label).join(', ')}`,'','MEINE AUSWERTUNG',m.finishReflection,'','Die Simulation bestätigt keine praktische Fahr-, Sicherungs- oder Pflegekompetenz.'].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='GTA_Transportmission_'+m.id+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const keys={KeyW:'gas',ArrowUp:'gas',KeyS:'brake',ArrowDown:'brake',KeyA:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right',ShiftLeft:'sprint',ShiftRight:'sprint'};
window.addEventListener('keydown',e=>{
 if(e.altKey||e.ctrlKey||e.metaKey||e.isComposing)return;
 const enter=e.code==='Enter'||e.code==='NumpadEnter';
 if(enter&&e.repeat){e.preventDefault();return;}
 if(modal.open){if(!loading&&e.code==='KeyF'&&t?.mode==='car'&&body.querySelector('[data-action="exit"]')){e.preventDefault();if(!e.repeat)exit();return;}if(!loading)dialogKeyboard(e);return;}
 if(!running||loading||inTextControl(e.target||document.activeElement))return;
 if(e.code==='Escape'){e.preventDefault();pause();return}
 if(e.code==='KeyM'){e.preventDefault();if(!e.repeat)mapPanel();return}
 if(e.code==='KeyJ'){e.preventDefault();if(!e.repeat)journal();return}
 if(enter){if((e.target||document.activeElement)?.closest?.('button,a[href]'))return;e.preventDefault();context();return}
 if(e.code==='KeyE'){e.preventDefault();if(!e.repeat)context();return}
 if(e.code==='KeyF'){e.preventDefault();if(!e.repeat){if(t?.mode==='car')exit();else Drive.input('interact',true)}return}
 if(e.code==='KeyC'){e.preventDefault();if(!e.repeat)Drive.input('camera',true);return}
 if(keys[e.code]){e.preventDefault();if(e.code.startsWith('Arrow'))$('#city').focus({preventScroll:true});Drive.input(keys[e.code],true)}
});
window.addEventListener('keyup',e=>{if(keys[e.code]&&readyWorld)Drive.input(keys[e.code],false)});
window.addEventListener('blur',()=>{A?.pauseMusic();stopVoice();if(running&&!modal.open)pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){A?.pauseMusic();stopVoice();if(running&&!modal.open)pause()}});
modal.addEventListener('cancel',e=>{e.preventDefault();closePanel()});$('#closeDialog').onclick=closePanel;$('#startBtn').onclick=()=>{A?.unlock();tutorial(true)};$('#helpBtn').onclick=()=>tutorial(false);$('#pauseBtn').onclick=pause;$('#journalBtn').onclick=journal;$('#mapBtn').onclick=mapPanel;$('#miniMapBtn').onclick=mapPanel;$('#objectiveBtn').onclick=journal;$('#contextBtn').onclick=context;$('#exitBtn').onclick=exit;$('#soundBtn').onclick=audioPanel;
document.querySelectorAll('[data-control]').forEach(b=>{const stop=e=>{e.preventDefault();Drive.input(b.dataset.control,false)};b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);Drive.input(b.dataset.control,true)};b.onpointerup=stop;b.onpointercancel=stop;b.onlostpointercapture=stop});
const homeCaption=$('#home .caption'),homeCaptionBase=homeCaption?.textContent||'';
$('#soundBtn').textContent='Einstellungen';renderCards();requestAnimationFrame(()=>window.drawCover?.($('#cover')));window.addEventListener('resize',()=>{if(running)Drive.resize();else window.drawCover?.($('#cover'))});
})();
